	protected static DecompileData mockData(DecompileResults decompileResults) {
		Function function = decompileResults.getFunction();
		Program program = function.getProgram();
		ProgramLocation location = new ProgramLocation(program, function.getEntryPoint());
		return new DecompileData(program, function, location, decompileResults, "", null, null);
	}

	/* @Test */
	public void testToggleBreakpointDecompilerNoAddress()
    {
		prepareDecompiler();
		DecompileResults results = new _Anon_MockDecompileResults_1(function);
		runSwing(() => decompilerProvider.getController().setDecompileData(mockData(results)));

		runSwing(() => assertFalse(breakpointMarkerPlugin.actionToggleBreakpoint
				.isEnabledForContext(decompilerProvider.getActionContext(null))));
	}

	/* @Test */
	public void testToggleBreakpointDecompilerOneAddress()
    {
		prepareDecompiler();
		DecompileResults results = new _Anon_MockDecompileResults_2(function);
		runSwing(() => decompilerProvider.getController().setDecompileData(mockData(results)));

		performEnabledAction(decompilerProvider, breakpointMarkerPlugin.actionToggleBreakpoint,
			false);
		DebuggerPlaceBreakpointDialog dialog =
			waitForDialogComponent(typeof(DebuggerPlaceBreakpointDialog));
		runSwing(() => dialog.okCallback());
		waitForPass(() => {
			LogicalBreakpoint lb = Unique.assertOne(breakpointService.getAllBreakpoints());
			assertEquals(State.INEFFECTIVE_ENABLED, lb.computeState());
			assertEquals(CommonSet.SWX.kinds(), lb.getKinds());
		});

		performEnabledAction(decompilerProvider, breakpointMarkerPlugin.actionToggleBreakpoint,
			true);
		waitForPass(() => {
			LogicalBreakpoint lb = Unique.assertOne(breakpointService.getAllBreakpoints());
			assertEquals(State.INEFFECTIVE_DISABLED, lb.computeState());
			assertEquals(CommonSet.SWX.kinds(), lb.getKinds());
		});
	}

	/* @Test */
	public void testToggleBreakpointDecompilerTwoAddresses()
    {
		prepareDecompiler();
		DecompileResults results = new _Anon_MockDecompileResults_3(function);
		runSwing(() => decompilerProvider.getController().setDecompileData(mockData(results)));

		waitOn(breakpointService.placeBreakpointAt(program, entry, 1,
			CommonSet.SWX.kinds(), ""));
		waitOn(breakpointService.placeBreakpointAt(program, entry.add(2), 1,
			CommonSet.SWX.kinds(), ""));
		waitForPass(() => {
			assertEquals(2, breakpointService.getAllBreakpoints().size());
		});

		performEnabledAction(decompilerProvider, breakpointMarkerPlugin.actionToggleBreakpoint,
			true);
		waitForPass(() => {
			Set<LogicalBreakpoint> all = breakpointService.getAllBreakpoints();
			assertEquals(2, all.size());
			foreach (LogicalBreakpoint lb in all) {
				assertEquals(State.INEFFECTIVE_DISABLED, lb.computeState());
			}
		});
	}

	/* @Test */
	public void testWithFunctionGraphPlugin()
    {
		functionGraphPlugin = addPlugin(tool, typeof(FunctionGraphPlugin));

		tool.removePlugins(List.of(breakpointMarkerPlugin));
		breakpointMarkerPlugin = addPlugin(tool, typeof(DebuggerBreakpointMarkerPlugin));

		tool.removePlugins(List.of(functionGraphPlugin));
	}

	protected void toggleInstallFunctionGraphPlugin()
    {
		if (functionGraphPlugin == null) {
			functionGraphPlugin = addPlugin(tool, typeof(FunctionGraphPlugin));
		}
		else {
			tool.removePlugins(List.of(functionGraphPlugin));
			functionGraphPlugin = null;
		}
	}

	protected void toggleInstallBreakointMarkerPlugin()
    {
		if (breakpointMarkerPlugin == null) {
			breakpointMarkerPlugin = addPlugin(tool, typeof(DebuggerBreakpointMarkerPlugin));
		}
		else {
			tool.removePlugins(List.of(breakpointMarkerPlugin));
			breakpointMarkerPlugin = null;
		}
	}

	/* @Test */
	public void testWithFunctionGraphPluginFrenetically()
    {
		Random rnd = new Random();
		for (int i = 0; i < 100; i++) {
			if (rnd.nextBoolean()) {
				toggleInstallFunctionGraphPlugin();
			}
			else {
				toggleInstallBreakointMarkerPlugin();
			}
		}
	}

	/* @Test */
	public void testWithFunctionGraphPluginAndOpenProgram()
    {
		functionGraphPlugin = addPlugin(tool, typeof(FunctionGraphPlugin));
		tool.removePlugins(List.of(breakpointMarkerPlugin));

		FGProvider functionGraphProvider = waitForComponentProvider(typeof(FGProvider));
		prepareDecompiler(); // Just to get a minimally meaningful program
		functionGraphProvider.setVisible(true);

		breakpointMarkerPlugin = addPlugin(tool, typeof(DebuggerBreakpointMarkerPlugin));
		tool.removePlugins(List.of(functionGraphPlugin));
		breakpointMarkerPlugin = addPlugin(tool, typeof(DebuggerBreakpointMarkerPlugin));
		tool.removePlugins(List.of(functionGraphPlugin));
		breakpointMarkerPlugin = addPlugin(tool, typeof(DebuggerBreakpointMarkerPlugin));
		tool.removePlugins(List.of(functionGraphPlugin));
	}

